+++ b/daemon/chargethreshold_helper_actions.actions
@@ -283,6 +283,18 @@ Description=Restore the battery charge limit after charging fully once.
 Policy=yes
 PolicyInactive=yes

+[org.kde.powerdevil.chargethresholdhelper.setfullchargetime]
+Name=Set time to charge battery fully by
+Description=Authenticate to set the time of day by which the battery is charged past its limit.
