@@ -14,6 +14,8 @@ using namespace Qt::StringLiterals;

 // Kept outside of the session so that the configured limits survive a reboot while charging fully once
 static const QString s_thresholdsBeforeFullChargePath = u"/var/lib/powerdevil/charge-thresholds-before-full-charge"_s;
+// Time of day (in minutes) by which the battery should be fully charged, set by an admin like the charge limit itself
+static const QString s_fullChargeTimePath = u"/var/lib/powerdevil/full-charge-time"_s;

 bool ChargeThresholdHelper::isChargingFullyOnce()
 {
@@ -25,6 +27,55 @@ void ChargeThresholdHelper::forgetThresholdsBeforeFullCharge()
     QFile::remove(s_thresholdsBeforeFullChargePath);
 }

+int ChargeThresholdHelper::fullChargeTime()
+{
+    QFile file(s_fullChargeTimePath);
+    if (!file.open(QIODevice::ReadOnly)) {
+        return -1;
+    }
+
+    bool ok = false;
+    const int minutes = file.readAll().trimmed().toInt(&ok);
+    return ok && minutes >= 0 && minutes < 24 * 60 ? minutes : -1;
+}
+
+ActionReply ChargeThresholdHelper::setfullchargetime(const QVariantMap &args)
+{
+    bool ok = false;
+    const int minutes = args.value(u"fullChargeTime"_s, -1).toInt(&ok);
+    if (!ok || minutes < -1 || minutes >= 24 * 60) {
+        auto reply = ActionReply::HelperErrorReply();
+        reply.setErrorDescription(u"Invalid full charge time"_s);
+        return reply;
+    }
+
+    if (minutes == -1) {
+        QFile::remove(s_fullChargeTimePath);
+        return ActionReply();
+    }
+
+    QDir().mkpath(QFileInfo(s_fullChargeTimePath).path());
+    QFile file(s_fullChargeTimePath);
+    if (!file.open(QIODevice::WriteOnly) || file.write(QByteArray::number(minutes)) == -1) {
+        auto reply = ActionReply::HelperErrorReply();
+        reply.setErrorDescription(u"Failed to write the full charge time"_s);
+        return reply;
+    }
+
+    return ActionReply();
+}
+
+ActionReply ChargeThresholdHelper::chargefullybytime(const QVariantMap &args)
+{
+    if (fullChargeTime() == -1) {
+        auto reply = ActionReply::HelperErrorReply();
+        reply.setErrorDescription(u"No full charge time is set"_s);
+        return reply;
+    }
+
+    return chargefullyonce(args);
+}
+
 ActionReply ChargeThresholdHelper::chargefullyonce(const QVariantMap &args)
 {
     Q_UNUSED(args);
