     if (QDBusConnection::sessionBus().interface()->isServiceRegistered(QStringLiteral("org.freedesktop.Notifications"))) {
@@ -737,8 +743,11 @@ void Core::onAcAdapterStateChanged(BatteryController::AcAdapterState state)

         m_powerCordUnpluggedNotification->sendEvent();

+        m_unpluggedSinceFullCharge = true;
         restoreChargeThresholdIfUnplugged();
     }
+
+    scheduleFullCharge();
 }

 void Core::onBatteryChargePercentChanged(int percent, const QString &udi)
@@ -1007,6 +1016,9 @@ void Core::onResumeFromSuspend() {
     emitBatteryChargePercentNotification(percent, 1000);

     m_batteryController->updateAcAdapterState();
+
+    // The timer doesn't advance while the system is asleep
+    scheduleFullCharge();
 }

 void Core::readChargeThreshold()
@@ -1043,8 +1055,54 @@ void Core::readChargeThreshold()
             restoreChargeThresholdIfUnplugged();
         }

+        m_fullChargeTime = data.value(QStringLiteral("fullChargeTime"), -1).toInt();
+        scheduleFullCharge();
+
         qCDebug(POWERDEVIL) << "Charge thresholds: start at" << chargeStartThreshold << "- stop at" << chargeStopThreshold << "- charging fully once"
-                            << chargingFullyOnce;
+                            << chargingFullyOnce << "- full charge time" << m_fullChargeTime;
+    });
+    job->start();
+}
+
+void Core::scheduleFullCharge()
+{
+    m_fullChargeTimer->stop();
+
+    if (m_fullChargeTime == -1 || m_chargingFullyOnce || m_chargeStopThreshold >= 100 || !m_unpluggedSinceFullCharge || !m_batteryController
+        || m_batteryController->acAdapterState() != BatteryController::Plugged) {
+        return;
+    }
+
+    // Charging the last part of the battery is slow, so lift the limit well ahead of time
+    constexpr int fullChargeLeadSecs = 2 * 60 * 60;
+
+    const QDateTime now = QDateTime::currentDateTime();
+    QDateTime fullChargeTime(now.date(), QTime(0, 0).addSecs(m_fullChargeTime * 60));
+    if (fullChargeTime < now) {
+        fullChargeTime = fullChargeTime.addDays(1);
+    }
+
+    const qint64 msecsToStart = now.msecsTo(fullChargeTime.addSecs(-fullChargeLeadSecs));
+    if (msecsToStart <= 0) {
+        chargeFullyByTime();
+    } else {
+        qCDebug(POWERDEVIL) << "Charging fully by" << fullChargeTime << "in" << msecsToStart / 1000 << "seconds";
+        m_fullChargeTimer->start(msecsToStart);
+    }
+}
+
+void Core::chargeFullyByTime()
+{
+    m_unpluggedSinceFullCharge = false;
+
+    KAuth::Action action(QStringLiteral("org.kde.powerdevil.chargethresholdhelper.chargefullybytime"));
+    action.setHelperId(QStringLiteral("org.kde.powerdevil.chargethresholdhelper"));
+    KAuth::ExecuteJob *job = action.execute();
+    connect(job, &KJob::result, this, [this, job] {
+        if (job->error()) {
+            qCWarning(POWERDEVIL) << "org.kde.powerdevil.chargethresholdhelper.chargefullybytime failed" << job->errorText();
+        }
+        readChargeThreshold();
     });
     job->start();
 }
